const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F0(1 − x/h), 0 ≤ x ≤ h' },
      { kind: 'text', payload: 'F0' },
      { kind: 'text', payload: 'F' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'W = 3/8 F0h' },
      { kind: 'text', payload: 'W/(F0h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = 70;
    var yBase = H - 70;
    var x1 = W - 55;
    var yTop = 60;
    var xMid = x0 + (x1 - x0) * 0.5;
    var yMid = yBase - (yBase - yTop) * 0.5;
    function line(pts) { return visualSdk.polyline(pts); }
    var shade = visualSdk.polyline([[x0, yBase], [x0, yTop], [xMid, yMid], [xMid, yBase], [x0, yBase]]);
    var curve = line([[x0, yTop], [x1, yBase]]);
    var xAxis = visualSdk.arrow(x0, yBase, x1 + 22, yBase, {});
    var yAxis = visualSdk.arrow(x0, yBase, x0, yTop - 12, {});
    var tickHalf = line([[xMid, yBase - 5], [xMid, yBase + 5]]);
    var tickH = line([[x1, yBase - 5], [x1, yBase + 5]]);
    var tickF0 = line([[x0 - 5, yTop], [x0 + 5, yTop]]);
    var guide = line([[xMid, yMid], [xMid, yBase]]);
    var dot = visualSdk.circle(xMid, yMid, 3);
    var labels = [
      { text: 'F(x) = F0(1 − x/h), 0 ≤ x ≤ h', x: x0 + 18, y: 30, fontSize: 15 },
      { text: 'F0', x: x0 - 32, y: yTop + 5, fontSize: 14 },
      { text: 'F', x: x0 - 26, y: 52, fontSize: 15 },
      { text: 'x', x: x1 + 18, y: yBase - 12, fontSize: 15 },
      { text: '0', x: x0 - 18, y: yBase + 19, fontSize: 13 },
      { text: 'h/2', x: xMid - 12, y: yBase + 24, fontSize: 14 },
      { text: 'h', x: x1 - 4, y: yBase + 24, fontSize: 14 },
      { text: 'W = 3/8 F0h', x: x0 + 18, y: yBase - 28, fontSize: 14 },
      { text: 'W/(F0h) = 3/8 = 0.375', x: x1 - 200, y: 32, fontSize: 15 }
    ];
    var children = [
      { type: 'path', pathId: 'shade', fill: '#a9c7e8', fillOpacity: 0.75, stroke: 'none' },
      { type: 'path', pathId: 'guide', stroke: '#7b8ca6', strokeDasharray: '5 4' },
      { type: 'path', pathId: 'curve', stroke: '#1f3b63', strokeWidth: 2.5 },
      { type: 'path', pathId: 'xaxis', stroke: '#26354a', strokeWidth: 1.6 },
      { type: 'path', pathId: 'yaxis', stroke: '#26354a', strokeWidth: 1.6 },
      { type: 'path', pathId: 'tickHalf', stroke: '#26354a', strokeWidth: 1.4 },
      { type: 'path', pathId: 'tickH', stroke: '#26354a', strokeWidth: 1.4 },
      { type: 'path', pathId: 'tickF0', stroke: '#26354a', strokeWidth: 1.4 },
      { type: 'path', pathId: 'dot', fill: '#1f3b63', stroke: 'none' }
    ];
    for (var i = 0; i < labels.length; i++) {
      children.push({ type: 'label', text: labels[i].text, x: labels[i].x, y: labels[i].y, fontSize: labels[i].fontSize, fill: '#26354a' });
    }
    return {
      schemaVersion: 1,
      sceneId: 'fig',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'guide', commands: guide },
        { id: 'curve', commands: curve },
        { id: 'xaxis', commands: xAxis },
        { id: 'yaxis', commands: yAxis },
        { id: 'tickHalf', commands: tickHalf },
        { id: 'tickH', commands: tickH },
        { id: 'tickF0', commands: tickF0 },
        { id: 'dot', commands: dot }
      ],
      root: { type: 'group', children: children }
    };
  }
};
